from collections import defaultdict

def analyze_repeating_blocks(file_path, block_size):
    with open(file_path, 'rb') as f:
        data = f.read()

    block_counts = defaultdict(int)
    for i in range(0, len(data), block_size):
        block = data[i:i+block_size]
        block_counts[block] += 1

    repeating_blocks = {block: count for block, count in block_counts.items() if count > 1}
    return repeating_blocks

file_path = "/home/ctfplayer/ctf_files/raw_ciphertexts.bin"
block_size = 16  # AES block size is 16 bytes

repeating_blocks = analyze_repeating_blocks(file_path, block_size)

if repeating_blocks:
    print("Repeating blocks detected:")
    for block, count in repeating_blocks.items():
        print(f"Block: {block.hex()} Count: {count}")
else:
    print("No repeating blocks detected.")

